package com.portfolio.features.project.entity; import jakarta.persistence.*; import java.util.*; import lombok.*; @Entity @Table(name="project_technologies") @Getter @Setter @NoArgsConstructor public class ProjectTechnology { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="project_id") private Project project; @Column(nullable=false) private String technology; private int sortOrder; }
